    for row in square:
        for num in row:
            all_numbers.append(num)

    # Check if numbers are 1 to n^2
    expected = set(range(1, n * n + 1))
    if set(all_numbers) != expected:
        return False

    # Calculate the magic constant
    magic_sum = sum(square[0])

    # Check rows
    for row in square:
        if sum(row) != magic_sum:
