def find_longest_repeating_subseq(s: str) -> int:
    n = len(s)
    # dp[i][j] represents the length of the longest repeating subsequence
    # using first i characters of s and first j characters of s
    # with the constraint that we don't use the same index for both subsequences
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if s[i - 1] == s[j - 1] and i != j:
                dp[i][j] = 1 + dp[i - 1][j - 1]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[n][n]
