def is_majority(arr, n, element):
    # Find the first occurrence of element using binary search
    def find_first(arr, n, element):
        low, high = 0, n - 1
        result = -1
        while low <= high:
            mid = (low + high) // 2
            if arr[mid] == element:
                result = mid
                high = mid - 1  # Continue searching in the left half
            elif arr[mid] < element:
                low = mid + 1
            else:
                high = mid - 1
        return result

    first_occurrence = find_first(arr, n, element)

    # If element is not found, it can't be a majority
    if first_occurrence == -1:
        return False

    # The majority element must appear more than n/2 times
    # So the element at index (first_occurrence + n // 2) should also be the element
    majority_index = first_occurrence + n // 2

    if majority_index < n and arr[majority_index] == element:
        return True
    else:
        return False
