        # Also consider just arr[i] itself as a subsequence of length 1
        if dp[i] == 1:
            dp[i] = arr[i]
        else:
            # dp[i] was updated from some j, but we should also compare with just arr[i]
            dp[i] = max(dp[i], arr[i])

    return max(dp)
