def is_subset_sum(arr, n, target_sum):
    # Create a DP table where dp[i][j] will be True if there is a subset
    # of arr[0..i-1] with sum equal to j
    dp = [[False] * (target_sum + 1) for _ in range(n + 1)]

    # Base case: sum 0 is always possible (empty subset)
    for i in range(n + 1):
        dp[i][0] = True

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, target_sum + 1):
            # If the current element is greater than the current sum,
            # we can't include it
            if arr[i - 1] > j:
                dp[i][j] = dp[i - 1][j]
            else:
                # Either include the element or exclude it
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - arr[i - 1]]

    return dp[n][target_sum]
