def first_Factorial_Divisible_Number(x):
    if x <= 1:
        return 1

    # We need to find the smallest n such that n! is divisible by x
    # We can do this by checking prime factorization of x and finding the minimum n
    # such that for each prime p with exponent e in x, the exponent of p in n! is >= e

    def prime_factorization(n):
        factors = {}
        d = 2
        while d * d <= n:
            while n % d == 0:
                factors[d] = factors.get(d, 0) + 1
                n //= d
            d += 1
        if n > 1:
            factors[n] = factors.get(n, 0) + 1
        return factors

    def exponent_in_factorial(p, n):
        """Calculate the exponent of prime p in n!"""
        count = 0
        while n > 0:
            count += n // p
            n //= p
        return count

    def min_n_for_prime(p, e):
        """Find the smallest n such that exponent of p in n! is at least e"""
        if e == 0:
            return 0
        lo, hi = 1, e * p  # upper bound
        while lo < hi:
            mid = (lo + hi) // 2
            if exponent_in_factorial(p, mid) >= e:
                hi = mid
            else:
                lo = mid + 1
        return lo

    factors = prime_factorization(x)
    result = 1
    for p, e in factors.items():
        n_p = min_n_for_prime(p, e)
        result = max(result, n_p)

    return result
```

