class Solution:
    def findKthSmallest(self, coins: List[int], k: int) -> int:
        import math
        from functools import reduce

        def gcd(a, b):
            while b:
                a, b = b, a % b
            return a

        def lcm(a, b):
            return a * b // gcd(a, b)

        def count_up_to(n, coins):
            """Count how many distinct positive integers <= n can be formed using any of the coins."""
            # Use inclusion-exclusion principle
            m = len(coins)
            count = 0
            for i in range(1, 1 << m):
                # Compute LCM of coins in this subset
                subset_lcm = 1
                bits = 0
                for j in range(m):
                    if i & (1 << j):
                        subset_lcm = lcm(subset_lcm, coins[j])
                        bits += 1
                        if subset_lcm > n:
                            break
                else:
                    if subset_lcm <= n:
                        if bits % 2 == 1:
                            count += n // subset_lcm
                        else:
                            count -= n // subset_lcm
            return count

        # Binary search on the answer
        lo, hi = 1, 2 * 10**18  # hi needs to be large enough

        while lo < hi:
            mid = (lo + hi) // 2
            if count_up_to(mid, coins) >= k:
                hi = mid
            else:
                lo = mid + 1

        return lo
