class Solution:
    def minimumRightShifts(self, nums: List[int]) -> int:
        n = len(nums)
        if n <= 1:
            return 0

        # Count the number of "drops" where nums[i] > nums[i+1]
        # In a rotated sorted array, there should be at most one such drop
        drop_count = 0
        drop_index = -1
        for i in range(n - 1):
            if nums[i] > nums[i + 1]:
                drop_count += 1
                drop_index = i
                if drop_count > 1:
                    return -1

        # If no drops, the array is already sorted
        if drop_count == 0:
            return 0

        # Check if the last element is less than the first element
        # This ensures the rotation is valid (the array is a rotated sorted array)
        if nums[-1] > nums[0]:
            return -1

        # The number of right shifts needed is n - 1 - drop_index
        # Because the drop is at index drop_index, meaning nums[drop_index] > nums[drop_index+1]
        # After right shifts, the element at drop_index+1 should become the first element
        # Number of right shifts to bring index drop_index+1 to position 0 is n - (drop_index + 1)
        return n - (drop_index + 1)
