class Solution:
    def minimumCost(self, source: str, target: str, original: List[str], changed: List[str], cost: List[int]) -> int:
        # Build adjacency list for the graph
        # Nodes are characters 'a' to 'z'
        # We need to find shortest path from each char to each other char

        # Initialize graph with infinity
        INF = float('inf')
        # dist[i][j] = minimum cost to change character chr(ord('a')+i) to chr(ord('a')+j)
        dist = [[INF] * 26 for _ in range(26)]

        # Distance from a character to itself is 0
        for i in range(26):
            dist[i][i] = 0

        # Add edges
        for i in range(len(original)):
            o = ord(original[i]) - ord('a')
            c = ord(changed[i]) - ord('a')
            # There might be multiple edges, keep the minimum cost
            if cost[i] < dist[o][c]:
                dist[o][c] = cost[i]

        # Floyd-Warshall algorithm to find all-pairs shortest paths
        for k in range(26):
            for i in range(26):
                for j in range(26):
                    if dist[i][k] != INF and dist[k][j] != INF:
                        if dist[i][k] + dist[k][j] < dist[i][j]:
                            dist[i][j] = dist[i][k] + dist[k][j]

        # Calculate total cost
        total_cost = 0
        for s, t in zip(source, target):
            if s == t:
                continue
            si = ord(s) - ord('a')
            ti = ord(t) - ord('a')
            if dist[si][ti] == INF:
                return -1
            total_cost += dist[si][ti]

        return total_cost
