class Solution:
    def numberOfStableArrays(self, zero: int, one: int, limit: int) -> int:
        MOD = 10**9 + 7

        # dp[z][o][last] = number of stable arrays with z zeros, o ones, ending with last (0 or 1)
        # We need to ensure that no run of identical elements exceeds limit.

        # dp[z][o][0] = number of ways to form array with z zeros, o ones, ending in 0
        # dp[z][o][1] = number of ways to form array with z zeros, o ones, ending in 1

        # Base cases:
        # dp[0][0][0] = 0, dp[0][0][1] = 0 (no elements)
        # For arrays with only zeros: dp[z][0][0] = 1 if 1 <= z <= limit, else 0
        # For arrays with only ones: dp[0][o][1] = 1 if 1 <= o <= limit, else 0

        dp = [[[0, 0] for _ in range(one + 1)] for _ in range(zero + 1)]

        # Initialize base cases for single-type arrays
        for z in range(1, zero + 1):
            if z <= limit:
                dp[z][0][0] = 1
            else:
                break  # Can't have more than limit consecutive zeros

        for o in range(1, one + 1):
            if o <= limit:
                dp[0][o][1] = 1
            else:
                break  # Can't have more than limit consecutive ones

        # Fill DP table
        for z in range(zero + 1):
            for o in range(one + 1):
                if z == 0 and o == 0:
                    continue

                # Calculate dp[z][o][0]: ending with 0
                # The last run of zeros has length k, where 1 <= k <= min(z, limit)
                # Before this run, we had z-k zeros and o ones, ending with 1
                # So dp[z][o][0] = sum over k=1 to min(z, limit) of dp[z-k][o][1]
                if z > 0:
                    total = 0
                    for k in range(1, min(z, limit) + 1):
                        total = (total + dp[z - k][o][1]) % MOD
                    dp[z][o][0] = total

                # Calculate dp[z][o][1]: ending with 1
                # The last run of ones has length k, where 1 <= k <= min(o, limit)
                # Before this run, we had z zeros and o-k ones, ending with 0
                # So dp[z][o][1] = sum over k=1 to min(o, limit) of dp[z][o-k][0]
                if o > 0:
                    total = 0
                    for k in range(1, min(o, limit) + 1):
                        total = (total + dp[z][o - k][0]) % MOD
                    dp[z][o][1] = total

        return (dp[zero][one][0] + dp[zero][one][1]) % MOD
