class Solution:
    def specialPerm(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)

        # Precompute compatibility: can nums[i] and nums[j] be adjacent?
        # Two numbers can be adjacent if one divides the other
        compatible = [[False] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i == j:
                    continue
                if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0:
                    compatible[i][j] = True

        # DP with bitmask
        # dp[mask][last] = number of ways to arrange the elements in mask, ending with element 'last'
        # mask is a bitmask where bit i is set if nums[i] is included
        total_masks = 1 << n
        dp = [[0] * n for _ in range(total_masks)]

        # Base case: single element permutations
        for i in range(n):
            dp[1 << i][i] = 1

        # Iterate over all masks
        for mask in range(1, total_masks):
            for last in range(n):
                if not (mask & (1 << last)):
                    continue
                if dp[mask][last] == 0:
                    continue
                # Try to add a new element 'next'
                for nxt in range(n):
                    if mask & (1 << nxt):
                        continue
                    # Check if last and nxt are compatible
                    if compatible[last][nxt]:
                        new_mask = mask | (1 << nxt)
                        dp[new_mask][nxt] = (dp[new_mask][nxt] + dp[mask][last]) % MOD

        # Sum up all full mask permutations
        full_mask = total_masks - 1
        result = 0
        for i in range(n):
            result = (result + dp[full_mask][i]) % MOD

        return result
```

