class Solution:
    def findValidPair(self, s: str) -> str:
        # Count frequency of each digit
        freq = {}
        for ch in s:
            freq[ch] = freq.get(ch, 0) + 1

        # Check each adjacent pair from left to right
        for i in range(len(s) - 1):
            first = s[i]
            second = s[i + 1]

            # First digit must not equal second digit
            if first == second:
                continue

            # Check if each digit appears exactly as many times as its numeric value
            first_val = int(first)
            second_val = int(second)

            if freq.get(first, 0) == first_val and freq.get(second, 0) == second_val:
                return first + second

        return ""
