class Solution:
    def longestMonotonicSubarray(self, nums: List[int]) -> int:
        if not nums:
            return 0

        n = len(nums)
        if n == 1:
            return 1

        max_len = 1

        # Check strictly increasing subarrays
        inc_len = 1
        for i in range(1, n):
            if nums[i] > nums[i - 1]:
                inc_len += 1
            else:
                inc_len = 1
            max_len = max(max_len, inc_len)

        # Check strictly decreasing subarrays
        dec_len = 1
        for i in range(1, n):
            if nums[i] < nums[i - 1]:
                dec_len += 1
            else:
                dec_len = 1
            max_len = max(max_len, dec_len)

        return max_len
