class Solution:
    def punishmentNumber(self, n: int) -> int:
        def can_partition(s: str, target: int) -> bool:
            """Check if string s can be partitioned into contiguous substrings that sum to target."""
            if not s:
                return target == 0
            # Try all possible first substrings
            for i in range(1, len(s) + 1):
                first = int(s[:i])
                if first > target:
                    break
                if can_partition(s[i:], target - first):
                    return True
            return False

        total = 0
        for i in range(1, n + 1):
            square = i * i
            s = str(square)
            if can_partition(s, i):
                total += square
        return total
```
